def prime_list(N):
    isPrime = [True for i in range(N + 1)]
    p = 2
    while p * p <= N:
        if isPrime[p]:
            for i in range(p * p, N + 1, p):
                isPrime[i] = False
        p += 1
    prime_nums = []
    for p in range(2, N):
        if isPrime[p]:
            prime_nums.append(p)
    return prime_nums

