class TreeNode: 
    def __init__(self, data): 
        self.data = data
        self.left = None
        self.right = None

def generate_tree(arr): 
    root = TreeNode(arr[0])

    for i in range(1, len(arr)): 
        curr = root 
        while True: 
            if arr[i] < curr.data: 
                if curr.left is None: 
                    curr.left = TreeNode(arr[i]) 
                    break
                else: 
                    curr = curr.left 
            elif arr[i] > curr.data: 
                if curr.right is None: 
                    curr.right = TreeNode(arr[i]) 
                    break
                else: 
                    curr = curr.right 
    return root

