class NaiveBayesClassifier:
    """
    A simple Naive Bayes classifier implementation
    """
    def __init__(self):
        self.classes = []
        self.word_counts = {}
        self.priors = {}

    def fit(self, X, y):
        """
        Train the classifier 
        X: List of documents
        y: List of labels
        """
        # compute class priors
        self.classes = list(set(y))
        for c in self.classes:
            self.priors[c] = (y.count(c) / len(y))

        # compute count of words
        for x, c in zip(X, y):
            words = x.split()
            for word in words:
                if (c, word) not in self.word_counts:
                    self.word_counts[(c, word)] = 0
                self.word_counts[(c, word)] += 1

    def predict(self, X):
        """
        Predict classes for a list of documents
        X: List of documents
        """
        pred_y = []
        for x in X:
            pred_classes = []
            # compute posterior for each class
            for c in self.classes:
                posterior = self.priors[c]
                for word in  x.split():
                    if (c, word) not in self.word_counts:
                        count = 0
                    else:
                        count = self.word_counts[(c, word)]
                    posterior *= (count + 1) / (sum([self.word_counts[(c, w)] for w in self.word_counts if w[0] == c]) +  len(self.word_counts))
                pred_classes.append((c, posterior))
            # select the most probable class
            p = max(pred_classes, key=lambda x: x[1])
            pred_y.append(p[0])

        return pred_y

def encrypt(string, shift):
    encrypted_string = ""

    for char in string:
        if char == ' ':
            encrypted_string += char
        else:
            encrypted_ascii = ord(char) + shift
            if encrypted_ascii > ord('z'):
                encrypted_ascii -= 26
            encrypted_string += chr(encrypted_ascii)

    return encrypted_string

def decrypt(encrypted_string, shift):
    decrypted_string = ""

    for char in encrypted_string:
        if char == ' ':
            decrypted_string += char
        else:
            decrypted_ascii = ord(char) - shift
            if decrypted_ascii < ord('a'):
                decrypted_ascii += 26
            decrypted_string += chr(decrypted_ascii)
    return decrypted_string

